    getShowCollapseItem: function getShowCollapseItem(formData, status) {
      if (formData) {
        var yhItem = getHiddenPCDict.find(function (a) {
          return a.name == formData.hiddenTypeLevel;
        });
        if (status == '8') {
          //判断县公司审核节点是否显示
          if (formData.status == '8') {
            //如果单子详情状态为8，说明为县公司审核节点 直接显示县公司节点
            return true;
          } else if (formData.status == '1') {
            //如果单子详情状态为1，说明为市公司审核节点 需要进行隐患分类标准进行判断
            if (yhItem) {
              if (['1', '2'].find(function (a) {
                return a == yhItem.id;
              }) != null) {
                //较大、重大隐患下判断是否是县公司
                if (formData.secondCompany && formData.secondCompany.slice(-2) != '99') {
                  //是
                  return true;
                }
              }
            }
          }
        } else if (status == '1') {
          //判断市公司审核节点是否显示
          if (formData.status == '1') {
            return true;
          }
        }
      }
      return false;
    },
